  },
  {
    "updateComponents": {
      "surfaceId": "bolognese-recipe",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "img-header",
            "content-container"
          ]
        },
        {
          "id": "img-header",
          "component": "Image",
          "url": "/assets/r_000321_01_1_bolognese-sauce.jpg",
          "fit": "cover",
          "variant": "header"
        },
        {
          "id": "content-container",
          "component": "Column",
          "children": [
            "header-section",
            "divider-1",
            "ingredients-section",
            "divider-2",
            "steps-section",
            "tips-card",
            "actions-row",
            "sources-section"
          ]
        },
        {
          "id": "header-section",
          "component": "Column",
          "children": [
            "title",
            "meta-row",
            "description"
          ]
        },
        {
          "id": "title",
          "component": "Text",
          "text": "Traditional Ragù alla Bolognese for 4",
          "variant": "h1"
        },
        {
          "id": "meta-row",
          "component": "Row",
          "align": "center",
          "children": [
            "icon-clock",
            "text-time",
            "icon-fire",
            "text-method"
          ]
        },
        {
          "id": "icon-clock",
          "component": "Icon",
          "name": {
            "path": "/assets/r_000242_01_6_clock.svg"
          }
        },
        {
          "id": "text-time",
          "component": "Text",
          "text": " 3.5 hours  ",
          "variant": "body"
        },
        {
          "id": "icon-fire",
          "component": "Icon",
          "name": {
            "path": "/assets/r_000321_01_5_fire.svg"
          }
        },
        {
          "id": "text-method",
          "component": "Text",
          "text": " Slow Simmer",
          "variant": "body"
        },
        {
          "id": "description",
          "component": "Text",
          "text": "This recipe draws from authentic sources like the Accademia Italiana della Cucina and Italian home cooks, scaled to serve 4 with a classic soffritto base, dual meats, milk for tenderness, and a 3-hour slow simmer for deep flavor. It yields about 1.2 kg sauce, enough for 400g dried tagliatelle.",
          "variant": "body"
        },
        {
          "id": "divider-1",
          "component": "Divider"
        },
        {
          "id": "ingredients-section",
          "component": "Column",
          "children": [
            "h-ingredients",
            "list-ingredients"
          ]
        },
        {
          "id": "h-ingredients",
          "component": "Text",
          "text": "Ingredients",
          "variant": "h2"
        },
        {
          "id": "list-ingredients",
          "component": "List",
          "direction": "vertical",
          "children": [
            "ing-1",
            "ing-2",
            "ing-3",
            "ing-4",
            "ing-5",
            "ing-6",
            "ing-7",
            "ing-8",
            "ing-9",
            "ing-10",
            "ing-11",
            "ing-12",
            "ing-13",
            "ing-14"
          ]
        },
        {
          "id": "ing-1",
          "component": "Text",
          "text": "• 300g coarsely ground beef (70-80% lean)",
          "variant": "body"
        },
        {
          "id": "ing-2",
          "component": "Text",
          "text": "• 300g ground pork",
          "variant": "body"
        },
        {
          "id": "ing-3",
          "component": "Text",
          "text": "• 50g pancetta, finely diced",
          "variant": "body"
        },
        {
          "id": "ing-4",
          "component": "Text",
          "text": "• 1 medium onion (150g), finely diced",
          "variant": "body"
        },
        {
          "id": "ing-5",
          "component": "Text",
          "text": "• 1 medium carrot (100g), finely diced",
          "variant": "body"
        },
        {
          "id": "ing-6",
          "component": "Text",
          "text": "• 1 celery stalk (80g), finely diced",
          "variant": "body"
        },
        {
          "id": "ing-7",
          "component": "Text",
          "text": "• 2 tbsp (30ml) olive oil",
          "variant": "body"
        },
        {
          "id": "ing-8",
          "component": "Text",
          "text": "• 50ml dry white wine (or red)",
          "variant": "body"
        },
        {
          "id": "ing-9",
          "component": "Text",
          "text": "• 2 tbsp (50g) tomato paste",
          "variant": "body"
        },
        {
          "id": "ing-10",
          "component": "Text",
          "text": "• 400ml tomato passata (or puree)",
          "variant": "body"
        },
        {
          "id": "ing-11",
          "component": "Text",
          "text": "• 100ml whole milk",
          "variant": "body"
        },
        {
          "id": "ing-12",
          "component": "Text",
          "text": "• 1 bay leaf",
          "variant": "body"
        },
        {
          "id": "ing-13",
          "component": "Text",
          "text": "• Salt and black pepper to taste",
          "variant": "body"
        },
        {
          "id": "ing-14",
          "component": "Text",
          "text": "• Pinch of nutmeg (optional)",
          "variant": "body"
        },
        {
          "id": "divider-2",
          "component": "Divider"
        },
        {
          "id": "steps-section",
          "component": "Column",
          "children": [
            "h-steps",
            "step-1",
            "step-2",
            "img-soffritto",
            "step-3",
            "step-4",
            "step-5",
            "step-6",
            "img-simmer",
            "step-7",
            "step-8"
          ]
        },
        {
          "id": "h-steps",
          "component": "Text",
          "text": "3-Hour Slow Simmer Steps",
          "variant": "h2"
        },
        {
          "id": "step-1",
          "component": "Text",
          "text": "1. In a large heavy pot over low heat, add olive oil and pancetta. Render fat for 5 minutes until crisp, no browning.",
          "variant": "body"
        },
        {
          "id": "step-2",
          "component": "Text",
          "text": "2. Add diced onion, carrot, and celery (soffritto). Cook covered on low for 10-15 minutes until soft and translucent, stirring occasionally.",
          "variant": "body"
        },
        {
          "id": "img-soffritto",
          "component": "Image",
          "url": "/assets/r_000321_01_2_italian-soffritto.jpg",
          "variant": "mediumFeature",
          "fit": "cover"
        },
        {
          "id": "step-3",
          "component": "Text",
          "text": "3. Increase to medium heat. Add beef and pork, breaking up with a spoon. Cook 10 minutes until meat loses raw color and starts browning, seasoning lightly with salt and pepper. Drain excess fat if needed.",
          "variant": "body"
        },
        {
          "id": "step-4",
          "component": "Text",
          "text": "4. Pour in white wine. Simmer on high until fully evaporated, about 2-3 minutes.",
          "variant": "body"
        },
        {
          "id": "step-5",
          "component": "Text",
          "text": "5. Stir in tomato paste, cooking 2 minutes to caramelize. Add passata, bay leaf, and nutmeg. Bring to a gentle boil.",
          "variant": "body"
        },
        {
          "id": "step-6",
          "component": "Text",
          "text": "6. Reduce to lowest heat, cover partially, and simmer 3 hours. Stir every 20-30 minutes; add a splash of water (20ml) if too thick. Sauce should reduce to thick, velvety consistency with fat separating slightly.",
          "variant": "body"
        },
        {
          "id": "img-simmer",
          "component": "Image",
          "url": "/assets/r_000321_01_3_ragu-simmering.jpg",
          "variant": "mediumFeature",
          "fit": "cover"
        },
        {
          "id": "step-7",
          "component": "Text",
          "text": "7. In last 15 minutes, stir in milk. Simmer uncovered, stirring often, until absorbed and silky. Remove bay leaf. Taste and adjust salt/pepper.",
          "variant": "body"
        },
        {
          "id": "step-8",
          "component": "Text",
          "text": "8. Serve with cooked tagliatelle, grated Parmigiano-Reggiano.",
          "variant": "body"
        },
        {
          "id": "tips-card",
          "component": "Card",
          "child": "tips-col"
        },
        {
          "id": "tips-col",
          "component": "Column",
          "children": [
            "h-tips",
            "text-tips"
          ]
        },
        {
          "id": "h-tips",
          "component": "Text",
          "text": "Cooking Tips",
          "variant": "h3"
        },
        {
          "id": "text-tips",
          "component": "Text",
          "text": "Use a heavy Dutch oven for even low heat. Total time: 3.5 hours. Freezes well up to 3 months. Pairs best with egg pasta, not spaghetti.",
          "variant": "body"
        },
        {
